import React, { useCallback, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Modal, ModalBody, ModalFooter, ModalHeader, Input, Label } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import { courseStatic } from 'config/constants';
import { getGlobalCurrentBatchUtils, getGlobalSchoolUtils } from 'utils/commonFunc';
import { addWishlistApi, assignStudentApi, deleteCallApi, fetchTodayApi, logCallApi } from 'actions/admin/mentorCalls';
import { guardianLine, todayCounts } from 'utils/mentorCalls';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import EmptyState from 'views/admin/Common/EmptyState';
import { SkeletonRows } from 'views/admin/Common/Loader';
import StatTile from 'views/admin/Common/StatTile';
import { ReportPaper } from 'views/admin/Common/ReportBits';
import LogCallModal from './LogCallModal';
import MenteeCard from './MenteeCard';
import StudentPickerModal from './StudentPickerModal';

// Today's mentees: call the guardian (the number is a link on a phone), record how it went, put a student on the wishlist for later,
// or add a student of your own to the list. The list fills up to the daily count the first time it is opened.
const TodayTab = ({ reloadKey, onChanged, toast, toastError }) => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const batchId = getGlobalCurrentBatchUtils()?.batchId;

  const [calls, setCalls] = useState([]);
  const [loading, setLoading] = useState(true);
  const [logging, setLogging] = useState(null);
  const [adding, setAdding] = useState(false);
  const [wishing, setWishing] = useState(null);
  const [removing, setRemoving] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      setCalls(await fetchTodayApi({ token, schoolId, batchId }));
    } catch (err) {
      toastError(err);
    }
    setLoading(false);
  }, [token, schoolId, batchId]);

  useEffect(() => {
    load();
  }, [load, reloadKey]);

  const { total, done, left } = todayCounts(calls);

  const saveLog = async body => {
    try {
      await logCallApi({ token, callId: logging.mentorCallId, body });
      toast('Call saved');
      load();
      onChanged();
    } catch (err) {
      toastError(err);
      throw err;
    }
  };

  const addStudent = async ({ studentId, date }) => {
    try {
      await assignStudentApi({ token, schoolId, studentId, callDate: date });
      toast(date ? 'Added to the list of that day' : "Added to today's list");
      load();
    } catch (err) {
      toastError(err);
      throw err;
    }
  };

  // from a call: the student is already known, only the note is asked
  const addWishlist = async ({ note, date }) => {
    try {
      await addWishlistApi({ token, schoolId, studentId: wishing.studentId, note, remindDate: date });
      toast('Saved to the wishlist');
      onChanged();
    } catch (err) {
      toastError(err);
      throw err;
    }
  };

  const remove = async () => {
    const call = removing;
    setRemoving(null);
    try {
      await deleteCallApi({ token, callId: call.mentorCallId });
      load();
    } catch (err) {
      toastError(err);
    }
  };

  return (
    <>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
        <StatTile label="Mentees today" value={total} />
        <StatTile label="Calls recorded" value={done} tone="good" />
        <StatTile label="Still to call" value={left} tone={left ? 'warn' : 'good'} />
      </div>
      <ReportPaper
        title="Today's mentees"
        intro="How it works: 1) Call the guardian on the number shown.  2) Press the purple button and write what they said.  3) Anything you remove is replaced by a new student the next time you open this page.  Feedback = what the guardian told you. Question = what the guardian asked the school."
        action={<CustomButton size="small" name="Add a student" onClick={() => setAdding(true)} />}>
        {loading && !calls.length ? (
          <SkeletonRows rows={3} avatar={false} />
        ) : !calls.length ? (
          <EmptyState
            compact
            bare
            icon="fas fa-phone-alt"
            title="No mentees for today"
            subtitle="Add a student with the button above."
          />
        ) : (
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))',
              gap: 16,
              marginTop: 8,
            }}>
            {calls.map(call => (
              <MenteeCard
                key={call.mentorCallId}
                call={call}
                onRecord={setLogging}
                onWishlist={setWishing}
                onRemove={setRemoving}
              />
            ))}
          </div>
        )}
      </ReportPaper>

      <LogCallModal call={logging} onSave={saveLog} onClose={() => setLogging(null)} />
      <StudentPickerModal
        isOpen={adding}
        title="Add a student"
        confirmLabel="Add to the list"
        dateLabel="Call date (empty = today)"
        onConfirm={addStudent}
        onClose={() => setAdding(false)}
      />
      <WishNote call={wishing} onSave={addWishlist} onClose={() => setWishing(null)} />
      <ConfirmModal
        size="md"
        confirmModalOpen={!!removing}
        confirmMessage={`Remove ${
          removing?.studentName || ''
        } from today's list? A new mentee is given the next time you open this page. (${courseStatic}: ${
          removing?.courseName || ''
        }, guardian: ${guardianLine(removing) || '--'})`}
        deleteConfirm={remove}
        deleteCancel={() => setRemoving(null)}
      />
    </>
  );
};

// A note (and a remind-on date) for a student put on the wishlist from today's list.
const WishNote = ({ call, onSave, onClose }) => {
  const [note, setNote] = useState('');
  const [date, setDate] = useState('');
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    setNote('');
    setDate('');
  }, [call]);
  const save = async () => {
    setSaving(true);
    try {
      await onSave({ note: note.trim(), date });
      onClose();
    } catch (err) {
      // the page already showed why
    }
    setSaving(false);
  };
  return (
    <Modal isOpen={!!call} toggle={onClose} centered>
      <ModalHeader toggle={onClose}>Save {call?.studentName} for later</ModalHeader>
      <ModalBody>
        <Label className="form-label">Note (optional)</Label>
        <Input
          maxLength={500}
          placeholder="Optional..."
          value={note}
          onChange={e => setNote(e.target.value)}
          autoFocus
        />
        <Label className="form-label mt-3">Remind me on (optional)</Label>
        <Input
          type="date"
          value={date}
          min={new Date().toISOString().substring(0, 10)}
          onChange={e => setDate(e.target.value)}
          style={{ height: 38 }}
        />
      </ModalBody>
      <ModalFooter style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 12 }}>
        <CustomButton variant="outlined" name="Cancel" onClick={onClose} />
        <CustomButton name="Save" showLoader loading={saving} disabled={saving} onClick={save} />
      </ModalFooter>
    </Modal>
  );
};

export default TodayTab;
