import React from 'react';
import PhoneIcon from '@material-ui/icons/Phone';
import StarBorderIcon from '@material-ui/icons/StarBorder';
import DeleteOutlineIcon from '@material-ui/icons/DeleteOutline';
import EventIcon from '@material-ui/icons/Event';
import colors from 'config/colors';
import CustomButton from 'components/CustomButton';
import ClampedText from 'views/admin/Common/ClampedText';
import { Chip } from 'views/admin/Promotion/components/StatusChip';
import {
  callStatusLabel,
  callStatusTone,
  dialNumber,
  isPending,
  queryStatusLabel,
  queryStatusTone,
} from 'utils/mentorCalls';

const BORDER = { good: '#2e7d32', bad: '#c62828', warn: '#b26a00', neutral: '#c9b3d9' };

const Initial = ({ name }) => (
  <div
    style={{
      width: 40,
      height: 40,
      borderRadius: 20,
      flexShrink: 0,
      background: `${colors.accent}1a`,
      color: colors.accent,
      fontWeight: 'bold',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
    {(name || '?').trim().charAt(0).toUpperCase()}
  </div>
);

// What the teacher wrote, under a small heading; an optional status chip sits at the right end of the heading row.
const Note = ({ heading, badge, children }) => (
  <div style={{ marginTop: 12 }}>
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
      <div
        style={{ fontSize: 11, fontWeight: 'bold', color: '#8b95a1', textTransform: 'uppercase', letterSpacing: 0.4 }}>
        {heading}
      </div>
      {badge}
    </div>
    <div style={{ fontSize: 13, color: '#2b3a4a', marginTop: 4 }}>{children}</div>
  </div>
);

const LinkButton = ({ icon: Icon, label, onClick, color = colors.accent }) => (
  <a
    onClick={onClick}
    style={{
      cursor: 'pointer',
      color,
      fontWeight: 'bold',
      fontSize: 13,
      display: 'inline-flex',
      alignItems: 'center',
      gap: 4,
    }}>
    <Icon style={{ fontSize: 18 }} />
    {label}
  </a>
);

// One mentee of the day as a card: who the student is, who to call (the number is a button), how the call went, what was said, and
// the buttons that fit - the big one records the call; saving the student for later or removing the call are quiet links.
const MenteeCard = ({ call, onRecord, onWishlist, onRemove }) => {
  const tone = callStatusTone(call.callStatus);
  const dial = dialNumber(call.guardianMobile);
  const pending = isPending(call);
  return (
    <div
      style={{
        background: '#fff',
        borderRadius: 8,
        borderLeft: `4px solid ${BORDER[tone]}`,
        boxShadow: '0 1px 4px rgba(0,0,0,0.12)',
        padding: 16,
        display: 'flex',
        flexDirection: 'column',
      }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
        <Initial name={call.studentName} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 'bold', fontSize: 15, color: '#1f2d3d' }}>{call.studentName}</div>
          <div style={{ fontSize: 12, color: '#8b95a1' }}>
            {[call.courseName, call.registerNumber && `Reg ${call.registerNumber}`].filter(Boolean).join(' · ')}
            {call.source === 'MANUAL' && ' · added by you'}
          </div>
        </div>
        <Chip label={callStatusLabel(call.callStatus)} tone={tone} />
      </div>

      <div
        style={{
          marginTop: 12,
          padding: '10px 12px',
          background: '#faf7fc',
          borderRadius: 6,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 8,
          flexWrap: 'wrap',
        }}>
        <div>
          <div style={{ fontSize: 11, color: '#8b95a1', textTransform: 'uppercase', fontWeight: 'bold' }}>
            Call the guardian
          </div>
          <div style={{ fontSize: 14, color: '#1f2d3d' }}>
            {call.guardianName || 'No guardian on record'}
            {call.guardianRelation ? ` (${call.guardianRelation.toLowerCase()})` : ''}
          </div>
        </div>
        {dial ? (
          <a
            href={`tel:${dial}`}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 6,
              border: `1.5px solid ${colors.accent}`,
              color: colors.accent,
              borderRadius: 18,
              padding: '4px 12px',
              fontWeight: 'bold',
              fontSize: 14,
            }}>
            <PhoneIcon style={{ fontSize: 16 }} />
            {call.guardianMobile}
          </a>
        ) : (
          <span style={{ color: '#8b95a1', fontSize: 13 }}>No number</span>
        )}
      </div>

      {!pending && (
        <>
          {call.feedback && (
            <Note heading="What the guardian said">
              <ClampedText text={call.feedback} title={`${call.studentName}: what the guardian said`} />
            </Note>
          )}
          {call.queries && (
            <Note
              heading="Guardian's question"
              badge={<Chip label={queryStatusLabel(call.queryStatus)} tone={queryStatusTone(call.queryStatus)} />}>
              <ClampedText text={call.queries} title={`${call.studentName}: guardian's question`} />
              {call.resolution && (
                <div style={{ marginTop: 6, color: '#5b6b7b' }}>
                  <b>Answer: </b>
                  <ClampedText
                    text={call.resolution}
                    title={`${call.studentName}: the answer`}
                    style={{ display: 'inline' }}
                  />
                </div>
              )}
            </Note>
          )}
          {call.followUpDate && (
            <div
              style={{ marginTop: 10, fontSize: 13, color: '#b26a00', display: 'flex', alignItems: 'center', gap: 4 }}>
              <EventIcon style={{ fontSize: 16 }} />
              Call again on {call.followUpDate}
            </div>
          )}
        </>
      )}

      <div style={{ flex: 1 }} />
      <div style={{ marginTop: 14, display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap' }}>
        <CustomButton
          name={pending ? 'I called - record it' : 'Edit what was recorded'}
          onClick={() => onRecord(call)}
        />
        <LinkButton icon={StarBorderIcon} label="Save for later" onClick={() => onWishlist(call)} />
        {pending && (
          <LinkButton icon={DeleteOutlineIcon} label="Remove" color="#c62828" onClick={() => onRemove(call)} />
        )}
      </div>
    </div>
  );
};

export default MenteeCard;
