import React, { useEffect, useState } from 'react';
import { Modal, ModalBody, ModalFooter, ModalHeader, Input, Label } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import {
  CALL_STATUSES,
  LOGGABLE_STATUSES,
  QUERY_STATUSES,
  formOfCall,
  guardianLine,
  isPending,
  logBody,
} from 'utils/mentorCalls';

const Help = ({ children }) => <div style={{ fontSize: 12, color: '#7d7d7d', margin: '-2px 0 6px' }}>{children}</div>;

const TONE = { good: '#2e7d32', bad: '#c62828', warn: '#b26a00', neutral: '#6b7280' };

// A row of choices that look like buttons you can press: every one has a coloured border, and the chosen one is filled with a tick.
const Choices = ({ options, meta, value, onChange }) => (
  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10 }}>
    {options.map(option => {
      const active = value === option;
      const color = TONE[meta[option].tone] || TONE.neutral;
      return (
        <span
          key={option}
          role="button"
          tabIndex={0}
          onClick={() => onChange(option)}
          onKeyDown={e => e.key === 'Enter' && onChange(option)}
          style={{
            cursor: 'pointer',
            userSelect: 'none',
            padding: '7px 16px',
            borderRadius: 20,
            border: `1.5px solid ${color}`,
            background: active ? color : '#fff',
            color: active ? '#fff' : color,
            fontWeight: 'bold',
            fontSize: 13,
          }}>
          {active ? '\u2713 ' : ''}
          {meta[option].label}
        </span>
      );
    })}
  </div>
);

// Record (or edit) how a call went: the outcome, what the guardian said, a query they raised (and its answer) and a follow-up date.
// `onSave(body)` sends it; the box closes when that resolves.
const LogCallModal = ({ call, onSave, onClose }) => {
  const [form, setForm] = useState(formOfCall(call));
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setForm(formOfCall(call));
    setTried(false);
  }, [call]);

  const set = (name, value) => setForm(prev => ({ ...prev, [name]: value }));
  const hasQuery = !!form.queries.trim();
  const editing = !isPending(call);
  const [tried, setTried] = useState(false);
  // an answered question needs the answer written, so the school can read it later
  const missingAnswer = hasQuery && form.queryStatus === 'RESOLVED' && !form.resolution.trim();

  const save = async () => {
    setTried(true);
    if (missingAnswer) return;
    setSaving(true);
    try {
      await onSave(logBody(form));
      onClose();
    } catch (err) {
      // the page already showed why
    }
    setSaving(false);
  };

  return (
    <Modal isOpen={!!call} toggle={onClose} size="lg" centered>
      <ModalHeader toggle={onClose}>
        {call?.studentName}
        <div style={{ fontSize: 13, fontWeight: 'normal', color: '#6b778a' }}>{guardianLine(call)}</div>
        {editing && (
          <div style={{ fontSize: 12, fontWeight: 'normal', color: '#b26a00', marginTop: 2 }}>
            You are changing a call that was already recorded. Press &ldquo;Save changes&rdquo; when you are done.
          </div>
        )}
      </ModalHeader>
      <ModalBody>
        <Label className="form-label">Outcome</Label>
        <Choices
          options={LOGGABLE_STATUSES}
          meta={CALL_STATUSES}
          value={form.callStatus}
          onChange={v => set('callStatus', v)}
        />

        <Label className="form-label mt-3">Feedback: What the guardian said</Label>
        <Help>What the guardian told you about the student: health, studies, behaviour, anything they shared.</Help>
        <Input
          type="textarea"
          rows={6}
          maxLength={2000}
          style={{ minHeight: 130, padding: '8px 12px' }}
          placeholder="Write what the guardian said..."
          value={form.feedback}
          onChange={e => set('feedback', e.target.value)}
        />

        <Label className="form-label mt-3">Guardian&apos;s question</Label>
        <Help>Anything the guardian asked the school on this call (leave empty if there was none).</Help>
        <Input
          type="textarea"
          rows={5}
          maxLength={2000}
          style={{ minHeight: 110, padding: '8px 12px' }}
          placeholder="Write the guardian's question..."
          value={form.queries}
          onChange={e =>
            setForm(prev => ({
              ...prev,
              queries: e.target.value,
              queryStatus: e.target.value.trim() ? prev.queryStatus || 'OPEN' : '',
            }))
          }
        />
        {hasQuery && (
          <>
            <Label className="form-label mt-3">Is the question answered?</Label>
            <Help>
              Pick &ldquo;Not answered yet&rdquo; if you still have to find the answer. Pick &ldquo;Answered&rdquo; when
              you gave it on this call or later.
            </Help>
            <Choices
              options={['OPEN', 'RESOLVED']}
              meta={QUERY_STATUSES}
              value={form.queryStatus}
              onChange={v => set('queryStatus', v)}
            />
          </>
        )}
        {hasQuery && form.queryStatus === 'RESOLVED' && (
          <>
            <Label className="form-label mt-3">The answer you gave to the guardian</Label>
            <Input
              type="textarea"
              rows={4}
              placeholder="Write the answer you gave..."
              style={{ minHeight: 90, padding: '8px 12px' }}
              maxLength={2000}
              value={form.resolution}
              invalid={tried && missingAnswer}
              onChange={e => set('resolution', e.target.value)}
            />
            {tried && missingAnswer && (
              <div style={{ color: '#c62828', fontSize: 13, marginTop: 6 }}>
                Write the answer you gave, or choose &ldquo;Not answered yet&rdquo; above.
              </div>
            )}
          </>
        )}

        <Label className="form-label mt-3">Follow-up date</Label>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <Input
            type="date"
            value={form.followUpDate}
            min={new Date().toISOString().substring(0, 10)}
            onChange={e => set('followUpDate', e.target.value)}
            style={{ height: 38, flex: 1 }}
          />
          {!!form.followUpDate && (
            <a style={{ cursor: 'pointer', color: '#c62828' }} onClick={() => set('followUpDate', '')}>
              Clear
            </a>
          )}
        </div>
      </ModalBody>
      <ModalFooter style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 12 }}>
        <CustomButton variant="outlined" name="Cancel" onClick={onClose} />
        <CustomButton
          name={editing ? 'Save changes' : 'Save call'}
          showLoader
          loading={saving}
          disabled={saving}
          onClick={save}
        />
      </ModalFooter>
    </Modal>
  );
};

export default LogCallModal;
