import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Modal, ModalBody, ModalFooter, ModalHeader, Input, Label } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import CustomSelect from 'components/CustomSelect';
import constants, { courseStatic, formStudentName } from 'config/constants';
import { getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import { fetchCourseStudentsApi, fetchPickerCoursesApi } from 'actions/admin/mentorCalls';

// "Pick a student": the class, then the student, with an optional note (the wishlist), a remind-on date (the wishlist) or a call date
// (a student added to a day's list). `onConfirm({ studentId, note, date })` does the work; the box closes when it resolves.
const StudentPickerModal = ({ isOpen, title, confirmLabel, withNote, dateLabel, onConfirm, onClose }) => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const isTeacher = useSelector(state => state.auth.loggedUserRole) === constants.roles.teacher;
  const employeeId = useSelector(state => state.auth.loggedUserId);
  const batchId = getGlobalCurrentBatchUtils()?.batchId;

  const [courses, setCourses] = useState([]);
  const [courseId, setCourseId] = useState(0);
  const [students, setStudents] = useState([]);
  const [studentId, setStudentId] = useState(0);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [note, setNote] = useState('');
  const [date, setDate] = useState('');
  const [saving, setSaving] = useState(false);
  const [tried, setTried] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    setNote('');
    setDate('');
    setStudentId(0);
    setTried(false);
    fetchPickerCoursesApi({ token, isTeacher, employeeId, batchId })
      .then(list => {
        setCourses(list);
        setCourseId(list[0]?.courseId || 0);
      })
      .catch(() => setCourses([]));
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || !courseId) {
      setStudents([]);
      return;
    }
    setStudentId(0);
    setLoadingStudents(true);
    fetchCourseStudentsApi({ token, courseId, batchId })
      .then(setStudents)
      .catch(() => setStudents([]))
      .finally(() => setLoadingStudents(false));
  }, [isOpen, courseId]);

  const confirm = async () => {
    setTried(true);
    if (!studentId) return;
    setSaving(true);
    try {
      await onConfirm({ studentId, note: note.trim(), date });
      onClose();
    } catch (err) {
      // the page already showed why
    }
    setSaving(false);
  };

  return (
    <Modal isOpen={!!isOpen} toggle={onClose} centered>
      <ModalHeader toggle={onClose}>{title}</ModalHeader>
      <ModalBody>
        <CustomSelect
          label={courseStatic}
          name="courseId"
          value={courseId}
          usePortal
          onChange={(name, value) => setCourseId(value)}
          options={courses.map(el => ({ label: el.name, value: el.courseId }))}
        />
        <div className="mt-3">
          <CustomSelect
            label="Student"
            name="studentId"
            value={studentId}
            usePortal
            loading={loadingStudents}
            placeholder="Select student"
            error={tried && !studentId}
            onChange={(name, value) => setStudentId(value)}
            options={students.map(el => ({
              label: `${formStudentName(el)} (${el.registerNumber})`,
              value: el.studentId,
            }))}
          />
        </div>
        {withNote && (
          <>
            <Label className="form-label mt-3">Note (optional)</Label>
            <Input maxLength={500} placeholder="Optional..." value={note} onChange={e => setNote(e.target.value)} />
          </>
        )}
        {dateLabel && (
          <>
            <Label className="form-label mt-3">{dateLabel}</Label>
            <Input
              type="date"
              value={date}
              min={new Date().toISOString().substring(0, 10)}
              onChange={e => setDate(e.target.value)}
              style={{ height: 38 }}
            />
          </>
        )}
      </ModalBody>
      <ModalFooter style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 12 }}>
        <CustomButton variant="outlined" name="Cancel" onClick={onClose} />
        <CustomButton name={confirmLabel} showLoader loading={saving} disabled={saving} onClick={confirm} />
      </ModalFooter>
    </Modal>
  );
};

export default StudentPickerModal;
