import React, { useCallback, useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import PhoneIcon from '@material-ui/icons/Phone';
import DeleteOutlineIcon from '@material-ui/icons/DeleteOutline';
import EventIcon from '@material-ui/icons/Event';
import CustomButton from 'components/CustomButton';
import colors from 'config/colors';
import { getGlobalSchoolUtils } from 'utils/commonFunc';
import {
  addWishlistApi,
  fetchWishlistApi,
  removeWishlistApi,
  scheduleWishlistApi,
  updateWishlistApi,
} from 'actions/admin/mentorCalls';
import { dialNumber } from 'utils/mentorCalls';
import ClampedText from 'views/admin/Common/ClampedText';
import ConfirmModal from 'views/admin/Common/ConfirmModal';
import EmptyState from 'views/admin/Common/EmptyState';
import { SkeletonRows } from 'views/admin/Common/Loader';
import { Pager, ReportPaper } from 'views/admin/Common/ReportBits';
import StudentPickerModal from './StudentPickerModal';

const PAGE_SIZE = 9;

// The two lists of the wishlist, in words a teacher uses: students still to call, and students already called.
const LISTS = [
  { value: 'ACTIVE', label: 'Still to call', hint: 'Students you saved to call later.' },
  { value: 'DONE', label: 'Already called', hint: 'Students you marked as called. Re-open one to call again.' },
];

const Row = ({ icon: Icon, children, color = '#5b6b7b' }) => (
  <div style={{ display: 'flex', alignItems: 'flex-start', gap: 6, fontSize: 13, color, marginTop: 6 }}>
    <Icon style={{ fontSize: 16, marginTop: 2 }} />
    <div style={{ minWidth: 0 }}>{children}</div>
  </div>
);

// The students saved to call later. "Call today" puts one on today's list; "Mark as called" moves it to the Already called list.
const WishlistTab = ({ onScheduled, toast, toastError }) => {
  const token = useSelector(state => state.auth.loggedUserToken);
  const schoolId = getGlobalSchoolUtils()?.schoolId;

  const [status, setStatus] = useState('ACTIVE');
  const [data, setData] = useState({ items: [], page: 1, totalPages: 0, totalElements: 0 });
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);
  const [removing, setRemoving] = useState(null);

  const load = useCallback(
    async (page = 1) => {
      setLoading(true);
      try {
        setData(await fetchWishlistApi({ token, status, page, size: PAGE_SIZE }));
      } catch (err) {
        toastError(err);
      }
      setLoading(false);
    },
    [token, status]
  );

  useEffect(() => {
    load(1);
  }, [load]);

  const act = async (work, message) => {
    try {
      await work();
      if (message) toast(message);
      load(1);
    } catch (err) {
      toastError(err);
    }
  };

  const addToWishlist = async ({ studentId, note, date }) => {
    try {
      await addWishlistApi({ token, schoolId, studentId, note, remindDate: date });
      load(1);
    } catch (err) {
      toastError(err);
      throw err;
    }
  };

  const items = data.items || [];
  const list = LISTS.find(el => el.value === status);

  return (
    <ReportPaper
      title="Wishlist"
      intro="Save a student here when you cannot call the guardian now. Come back later and call from this list."
      action={<CustomButton size="small" name="Save a student" onClick={() => setAdding(true)} />}>
      <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 12, margin: '8px 0 16px' }}>
        <div
          style={{
            display: 'inline-flex',
            border: `1.5px solid ${colors.accent}`,
            borderRadius: 20,
            overflow: 'hidden',
          }}>
          {LISTS.map(el => (
            <span
              key={el.value}
              role="button"
              tabIndex={0}
              onClick={() => setStatus(el.value)}
              onKeyDown={e => e.key === 'Enter' && setStatus(el.value)}
              style={{
                cursor: 'pointer',
                padding: '6px 18px',
                fontWeight: 'bold',
                fontSize: 13,
                background: status === el.value ? colors.accent : '#fff',
                color: status === el.value ? '#fff' : colors.accent,
              }}>
              {el.label}
            </span>
          ))}
        </div>
        <span style={{ fontSize: 12, color: '#7d7d7d' }}>{list.hint}</span>
      </div>

      {loading && !items.length ? (
        <SkeletonRows rows={3} avatar={false} />
      ) : !items.length ? (
        <EmptyState
          compact
          bare
          icon="fas fa-star"
          title={status === 'ACTIVE' ? 'No student saved to call later' : 'Nobody marked as called yet'}
          subtitle={
            status === 'ACTIVE' ? 'Use "Save a student", or "Save for later" on a student in Today.' : undefined
          }
        />
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: 16 }}>
          {items.map(item => {
            const dial = dialNumber(item.guardianMobile);
            return (
              <div
                key={item.wishlistId}
                style={{
                  background: '#fff',
                  borderRadius: 8,
                  boxShadow: '0 1px 4px rgba(0,0,0,0.12)',
                  padding: 16,
                  borderLeft: '4px solid #c9b3d9',
                }}>
                <div style={{ fontWeight: 'bold', fontSize: 15, color: '#1f2d3d' }}>{item.studentName}</div>
                <div style={{ fontSize: 12, color: '#8b95a1' }}>
                  {item.registerNumber && `Reg ${item.registerNumber}`}
                </div>
                <Row icon={PhoneIcon}>
                  {item.guardianName || 'No guardian on record'}
                  {dial && (
                    <>
                      {' · '}
                      <a href={`tel:${dial}`} style={{ color: colors.accent, fontWeight: 'bold' }}>
                        {item.guardianMobile}
                      </a>
                    </>
                  )}
                </Row>
                {item.note && (
                  <div
                    style={{
                      marginTop: 10,
                      padding: '8px 10px',
                      background: '#faf7fc',
                      borderRadius: 6,
                      fontSize: 13,
                    }}>
                    <ClampedText text={item.note} title={`${item.studentName}: your note`} />
                  </div>
                )}
                {item.remindDate && (
                  <Row icon={EventIcon} color="#b26a00">
                    Remind me on {item.remindDate}
                  </Row>
                )}
                {item.lastCallDate && (
                  <div style={{ marginTop: 8, fontSize: 12, color: '#7d7d7d' }}>
                    Last call: {item.lastCallDate}
                    {item.lastFeedback && (
                      <ClampedText text={item.lastFeedback} title={`${item.studentName}: last call`} lines={2} />
                    )}
                  </div>
                )}
                <div style={{ marginTop: 14, display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap' }}>
                  {status === 'ACTIVE' ? (
                    <>
                      <CustomButton
                        size="small"
                        name="Call today"
                        onClick={() =>
                          act(async () => {
                            await scheduleWishlistApi({ token, wishlistId: item.wishlistId });
                            onScheduled();
                          }, "Added to today's list")
                        }
                      />
                      <a
                        style={{ cursor: 'pointer', color: colors.accent, fontWeight: 'bold', fontSize: 13 }}
                        onClick={() =>
                          act(() =>
                            updateWishlistApi({
                              token,
                              wishlistId: item.wishlistId,
                              body: { note: item.note, remindDate: item.remindDate, status: 'DONE' },
                            })
                          )
                        }>
                        Mark as called
                      </a>
                    </>
                  ) : (
                    <CustomButton
                      size="small"
                      variant="outlined"
                      name="Call again"
                      onClick={() =>
                        act(() =>
                          updateWishlistApi({
                            token,
                            wishlistId: item.wishlistId,
                            body: { note: item.note, remindDate: item.remindDate, status: 'ACTIVE' },
                          })
                        )
                      }
                    />
                  )}
                  <a
                    style={{
                      cursor: 'pointer',
                      color: '#c62828',
                      fontWeight: 'bold',
                      fontSize: 13,
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: 2,
                    }}
                    onClick={() => setRemoving(item)}>
                    <DeleteOutlineIcon style={{ fontSize: 16 }} />
                    Remove
                  </a>
                </div>
              </div>
            );
          })}
        </div>
      )}
      {data.totalPages > 1 && (
        <Pager
          from={(data.page - 1) * PAGE_SIZE + 1}
          to={Math.min(data.totalElements, data.page * PAGE_SIZE)}
          total={data.totalElements}
          hasPrev={data.page > 1}
          hasNext={data.page < data.totalPages}
          disabled={loading}
          onPrev={() => load(data.page - 1)}
          onNext={() => load(data.page + 1)}
        />
      )}

      <StudentPickerModal
        isOpen={adding}
        withNote
        title="Save a student for later"
        confirmLabel="Save"
        dateLabel="Remind me on (optional)"
        onConfirm={addToWishlist}
        onClose={() => setAdding(false)}
      />
      <ConfirmModal
        size="md"
        confirmModalOpen={!!removing}
        confirmMessage={`Remove ${removing?.studentName || ''} from the wishlist?`}
        deleteConfirm={() => {
          const item = removing;
          setRemoving(null);
          act(() => removeWishlistApi({ token, wishlistId: item.wishlistId }));
        }}
        deleteCancel={() => setRemoving(null)}
      />
    </ReportPaper>
  );
};

export default WishlistTab;
