import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import { useHistory, useLocation } from 'react-router-dom';
import { Paper, Tab, Tabs } from '@material-ui/core';
import colors from 'config/colors';
import constants from 'config/constants';
import { store } from 'index';
import { showToast } from 'actions/admin/auth';
import { formResMessage, getGlobalSchoolUtils } from 'utils/commonFunc';
import EmptyState from 'views/admin/Common/EmptyState';
import TodayTab from './TodayTab';
import WishlistTab from './WishlistTab';

const toast = (message, type = 'success') => store.dispatch(showToast(message, type));
// the backend answers an error with Spring's body ({ detail }); the shared message only reads details / message
const toastError = err => {
  const detail = err?.response?.data?.detail;
  toast(typeof detail === 'string' && detail ? detail : formResMessage(err), 'error');
};

// the tab is in the address (?tab=wishlist), so a refresh or a link lands on the same tab, like the other tabbed pages
const TABS = [
  { key: 'today', label: 'Today' },
  { key: 'wishlist', label: 'Wishlist' },
];

// Mentor calls, the process: the teacher (or the admin) calls the guardian of each of today's mentees and records how it went.
// The same calls can be made on the phone in the Scholae app. What was recorded is read back in Reports > Mentor calls report.
const MentorCalls = () => {
  const schoolId = getGlobalSchoolUtils()?.schoolId;
  const history = useHistory();
  const location = useLocation();
  const tabKey = new URLSearchParams(location.search).get('tab');
  const tab = Math.max(
    0,
    TABS.findIndex(item => item.key === tabKey)
  );
  // a call recorded or a student scheduled changes the other tab: it reloads when this number changes
  const [reloadKey, setReloadKey] = useState(0);
  const bump = () => setReloadKey(key => key + 1);

  if (!schoolId) {
    return (
      <EmptyState
        icon="fas fa-school"
        title="Select a school first"
        subtitle="Mentor calls work on one school at a time."
      />
    );
  }

  return (
    <>
      <Paper square style={{ marginBottom: 20 }}>
        <Tabs
          value={tab}
          onChange={(e, index) => history.push(`${location.pathname}?tab=${TABS[index].key}`)}
          indicatorColor=""
          textColor="inherit"
          variant="scrollable"
          scrollButtons="off">
          {TABS.map((item, index) => (
            <Tab
              key={item.key}
              label={item.label}
              style={{
                fontWeight: 'bold',
                minWidth: 140,
                color: tab === index ? colors.accent : '',
                borderBottom: tab === index ? `3px solid ${colors.accent}` : '3px solid transparent',
              }}
            />
          ))}
        </Tabs>
      </Paper>
      {tab === 0 && <TodayTab reloadKey={reloadKey} onChanged={bump} toast={toast} toastError={toastError} />}
      {tab === 1 && <WishlistTab onScheduled={bump} toast={toast} toastError={toastError} />}
    </>
  );
};

const MentorCallsPage = () => {
  const role = useSelector(state => state.auth.loggedUserRole);
  if (![constants.roles.admin, constants.roles.SA, constants.roles.teacher].includes(role)) {
    return (
      <EmptyState
        icon="fas fa-lock"
        title="Not available for your role"
        subtitle="Mentor calls are for teachers and admins."
      />
    );
  }
  return <MentorCalls />;
};

export default MentorCallsPage;
